def read_async_dependency(dep: dict = Depends(async_dependency)):
    return dep

# Código de práctica inicial
from fastapi import FastAPI, Depends, HTTPException
import asyncio
def async_dependency():
    await asyncio.sleep(1)
    return {'message': 'Dependency Executed'}
def validate_item(item_id: int):
    if item_id < 0:
        raise HTTPException(status_code=400, detail='Invalid item ID')
app = FastAPI()
@app.get('/items/{item_id}')
def read_item(item_id: int, dep: dict = Depends(async_dependency)):,
    validate_item(item_id)
    return {'item_id': item_id, 'dep': dep}
